package com.pointverse.app;
import android.test.InstrumentationTestCase;import java.io.*;import java.util.*;import org.json.*;
@SuppressWarnings("deprecation")
public final class DemoDataTest extends InstrumentationTestCase {
 PointStore demo,formal;String dn,fn;
 protected void setUp()throws Exception{super.setUp();dn="test-points-"+UUID.randomUUID()+".db";fn="formal-"+UUID.randomUUID()+".db";demo=new PointStore(getInstrumentation().getTargetContext(),dn);formal=new PointStore(getInstrumentation().getTargetContext(),fn);}
 protected void tearDown()throws Exception{for(PointStore store:new PointStore[]{demo,formal}){File media=store.audio.getParentFile();store.close();PointStore.removeTree(media);}getInstrumentation().getTargetContext().deleteDatabase(dn);getInstrumentation().getTargetContext().deleteDatabase(fn);super.tearDown();}
 DemoData data()throws Exception{return new DemoData(getInstrumentation().getTargetContext(),demo);}
 public void testCannotGenerateOrClearFormalLibrary()throws Exception{String id=formal.createText("正式想法","不改变");try{new DemoData(getInstrumentation().getTargetContext(),formal);fail();}catch(IllegalArgumentException expected){}assertEquals("不改变",formal.get(id).body);}
 public void testAppendAndMemorySamplesNeedNoModel()throws Exception {assertEquals(100,data().append(100,false));assertEquals(24,data().append(24,true));assertEquals(124,DemoData.count(demo));assertEquals(4,demo.memories().size());for(PointStore.Point p:demo.list("")){assertNull(p.path);assertFalse(p.body.isEmpty());assertEquals(3,new JSONArray(p.embedding).length());}assertEquals(0,DemoData.count(formal));}
 public void testIosGlobeCorpusIsIdempotentAndUsesBuiltInCoordinates()throws Exception{assertEquals(1024,data().globe());assertEquals(0,data().globe());assertEquals(1024,DemoData.count(demo));UniverseScene.State state=new UniverseScene.State();state.demo=true;UniverseScene scene=new UniverseScene(demo.list(""),new SemanticIndex(getInstrumentation().getTargetContext()),state);PointStore.Point p=demo.list("").get(0);JSONArray vector=new JSONArray(p.embedding);UniverseScene.Node node=scene.nodes.get(p.id);assertEquals(vector.getDouble(0),node.unit.x,.000001);assertEquals(vector.getDouble(1),node.unit.y,.000001);}
 public void testClearRemovesOnlyDemoDataAndItsAttachments()throws Exception {String id=formal.createText("正式想法","保留");data().append(10,false);File demoFile=new File(demo.audio,"test-file"),formalFile=new File(formal.audio,"keep-file");try(FileOutputStream out=new FileOutputStream(demoFile)){out.write(1);}try(FileOutputStream out=new FileOutputStream(formalFile)){out.write(2);}data().clear();assertEquals(0,DemoData.count(demo));assertFalse(demoFile.exists());assertTrue(demo.audio.isDirectory());assertTrue(demo.staging.isDirectory());assertTrue(formalFile.isFile());assertEquals("保留",formal.get(id).body);}
 public void testDemoLibraryCannotReachCloudSync()throws Exception {CloudSync.Remote denied=new CloudSync.Remote(){public JSONObject json(String p,String m,String t,JSONObject b){throw new AssertionError("不应请求云端");}public void upload(String t,String h,File f){throw new AssertionError();}public void download(String p,String t,File f,long max,String h,long n){throw new AssertionError();}};try{new CloudSync(demo,denied).versions("token");fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("测试库"));}}
}
